        private static Sprite[] _sprites = null;
        public static Sprite Icon(int idx)
        {
            if (_sprites == null)
            {
                _sprites = new Sprite[] {
                    CreatePixelSprite(WagePower, 32, 32, 100f), CreatePixelSprite(DoctorFriend, 32, 32, 100f), CreatePixelSprite(WaterMerchant, 32, 32, 100f), CreatePixelSprite(AlcoholMerchant, 32, 32, 100f),
                    CreatePixelSprite(LuckScout, 32, 32, 100f), CreatePixelSprite(RiskTaker, 32, 32, 100f), CreatePixelSprite(WineLover, 32, 32, 100f), CreatePixelSprite(HonestDealer, 32, 32, 100f),
                    CreatePixelSprite(SmilingTiger, 32, 32, 100f), CreatePixelSprite(ThiefMagnet, 32, 32, 100f), CreatePixelSprite(BadLuck, 32, 32, 100f), CreatePixelSprite(BadReputation, 32, 32, 100f),
                    CreatePixelSprite(SecurityInformant, 32, 32, 100f), CreatePixelSprite(WageTouch, 32, 32, 100f), CreatePixelSprite(Detective, 32, 32, 100f), CreatePixelSprite(HatedByAll, 32, 32, 100f),
                    CreatePixelSprite(Madness, 32, 32, 100f), CreatePixelSprite(DestinyDice, 32, 32, 100f), CreatePixelSprite(Wanderer, 32, 32, 100f), CreatePixelSprite(Infamous, 32, 32, 100f),
                    CreatePixelSprite(DryAir, 32, 32, 100f), CreatePixelSprite(Cannibal, 32, 32, 100f)
                };
            }
            if (idx >= 0 && idx < _sprites.Length) return _sprites[idx];
            return null;
        }
        public static Sprite CreatePixelSprite(Color[] pixels, int w, int h, float ppu)
        {
            if (pixels == null || pixels.Length != w * h) return null;
            Color[] flipped = new Color[pixels.Length];
            for (int y = 0; y < h; y++)
                for (int x = 0; x < w; x++)
                    flipped[(h - 1 - y) * w + x] = pixels[y * w + x]; // Y 翻转（PIL 顶行在前→SetPixels 底行在前）
            Texture2D tex = new Texture2D(w, h, TextureFormat.RGBA32, false);
            tex.filterMode = FilterMode.Point;
            tex.wrapMode = TextureWrapMode.Clamp;
            tex.hideFlags = HideFlags.DontSave;
            tex.SetPixels(flipped);
            tex.Apply();
            return Sprite.Create(tex, new Rect(0, 0, w, h), new Vector2(0.5f, 0.5f), ppu);
        }
    }
